starterCodeJson.code:
// Question 1 — the cover page of the SRS template (Wiegers): fill every field, remove every <placeholder>.
const COVER = {
  title: 'Software Requirements Specification',
  project: '<Project name>',
  version: '<1.0>',
  preparedBy: '<Your full name - Student ID>',
  organization: '<Organization>',
  dateCreated: '<yyyy-mm-dd>',
};

// Question 2 — context diagram as a Mermaid flowchart (paste into https://mermaid.live to see it).
// The system = ONE circle. External entities = rectangles. One labelled arrow per direction; label = the DATA.
const CONTEXT_DIAGRAM = `
flowchart LR
  S((System name))
  E1[External entity] -->|data in| S
  S -->|data out| E1
`;

// Question 3 — use case diagram (PlantUML: paste into https://www.plantuml.com/plantuml) + the two tables of the template.
const USE_CASE_DIAGRAM = `
@startuml
left to right direction
actor "Actor name" as A1
rectangle "System name" {
  usecase "Verb Object" as UC1
}
A1 --> UC1
@enduml
`;

// Table "# | Actor | Description" — one object per actor of the diagram (same names).
const ACTORS = [
  { name: 'Actor name', description: '' },
];

// Table "# | Use Case | Actors | Description" — one object per use case (same names as the diagram).
const USE_CASES = [
  { id: 'UC-01', name: 'Verb Object', actors: ['Actor name'], description: '' },
];

// Question 4 — conceptual ERD (Mermaid erDiagram) + the entity table of the template.
const ERD = `
erDiagram
  ENTITY_A ||--o{ ENTITY_B : verb
  ENTITY_A {
    string entityAId PK
    string name
  }
`;

// Table "# | Entity | Description" (+ key attributes) — one object per entity of the ERD.
const ENTITIES = [
  { name: 'ENTITY_A', description: '', attributes: ['entityAId'] },
];

solutionCodeJson.code:
// Question 1 — copy the system name EXACTLY from the paper; the grader cannot know your name, any real one passes.
const COVER = {
  title: 'Software Requirements Specification',
  project: 'FreshBox Meal-Kit Subscription Platform',
  version: '1.0',
  preparedBy: 'Nguyen Van An - SE180123',
  organization: 'FPT University, Ho Chi Minh City campus',
  dateCreated: '2026-11-05',
};

// Question 3 — use case diagram consistent with Question 2 (same actors), plus the actor and use case tables.
const USE_CASE_DIAGRAM = `@startuml
left to right direction
actor Customer
actor "Menu Planner" as MP
actor "Warehouse Staff" as WS
actor Administrator as AD
actor "Payment Gateway" as PG
actor "Delivery Partner" as DP
actor "Notification Service" as NS
rectangle "FreshBox Meal-Kit Subscription Platform" {
  usecase "Register Account" as UC1
  usecase "Subscribe to Plan" as UC2
  usecase "Save Payment Card" as UC3
  usecase "Apply Promotion Code" as UC4
  usecase "Choose Weekly Recipes" as UC5
  usecase "Skip or Pause Subscription" as UC6
  usecase "Charge Weekly Subscription" as UC7
  usecase "Track Delivery" as UC8
  usecase "Rate Recipe" as UC9
  usecase "Report Box Problem" as UC10
  usecase "Publish Weekly Menu" as UC11
  usecase "View Packing List" as UC12
  usecase "Mark Box Packed" as UC13
  usecase "Request Shipment" as UC14
  usecase "Review Problem Report" as UC15
  usecase "Issue Credit" as UC16
  usecase "Manage Staff Accounts" as UC17
  usecase "Manage Plans and Prices" as UC18
  usecase "View Revenue and Churn Reports" as UC19
  usecase "Send Notification" as UC20
}
Customer --> UC1
Customer --> UC2
Customer --> UC5
Customer --> UC6
Customer --> UC8
Customer --> UC9
Customer --> UC10
UC2 ..> UC3 : <<include>>
UC4 ..> UC2 : <<extend>>
UC3 --> PG
UC7 --> PG
UC7 ..> UC20 : <<include>>
MP --> UC11
WS --> UC12
WS --> UC13
UC13 ..> UC14 : <<include>>
UC14 --> DP
DP --> UC8
AD --> UC15
UC16 ..> UC15 : <<extend>>
AD --> UC17
AD --> UC18
AD --> UC19
UC20 --> NS
@enduml
`;

const ACTORS = [
  {
    name: 'Customer',
    description: 'A person who subscribes to a FreshBox plan, chooses weekly recipes, follows deliveries, rates recipes and reports problems with a box.',
  },
  {
    name: 'Menu Planner',
    description: 'FreshBox staff member who creates recipes with ingredients, nutrition facts and allergens and publishes the weekly menu.',
  },
  {
    name: 'Warehouse Staff',
    description: 'Staff in the packing warehouse who use the packing list, pack each box, mark it packed and print its shipping label.',
  },
  {
    name: 'Administrator',
    description: 'Manages staff accounts, plans and prices, reviews problem reports, issues credits and reads revenue and churn reports.',
  },
  {
    name: 'Payment Gateway',
    description: 'External payment system (VNPay) that tokenises payment cards and executes the weekly charges, returning the result.',
  },
  {
    name: 'Delivery Partner',
    description: 'External courier (GHN) that receives shipment requests through its API and sends back delivery status updates.',
  },
  {
    name: 'Notification Service',
    description: 'External service that delivers the e-mails and SMS messages the platform sends to customers and staff.',
  },
];

const USE_CASES = [
  {
    id: 'UC-01',
    name: 'Register Account',
    actors: ['Customer'],
    description: 'The customer creates a FreshBox account with contact details and a delivery address.',
  },
  {
    id: 'UC-02',
    name: 'Subscribe to Plan',
    actors: ['Customer'],
    description: 'The customer chooses a plan by meals per week and people and starts a weekly subscription.',
  },
  {
    id: 'UC-03',
    name: 'Save Payment Card',
    actors: ['Payment Gateway'],
    description: 'Included in subscribing: the card is tokenised by the payment gateway and the token is stored.',
  },
  {
    id: 'UC-04',
    name: 'Apply Promotion Code',
    actors: [],
    description: 'Optional extension of subscribing: a valid promotion code discounts the first box.',
  },
  {
    id: 'UC-05',
    name: 'Choose Weekly Recipes',
    actors: ['Customer'],
    description: 'Before the Wednesday cut-off the customer picks next week recipes and the portions of each.',
  },
  {
    id: 'UC-06',
    name: 'Skip or Pause Subscription',
    actors: ['Customer'],
    description: 'The customer skips one coming week or pauses the subscription until a chosen date.',
  },
  {
    id: 'UC-07',
    name: 'Charge Weekly Subscription',
    actors: ['Payment Gateway'],
    description: 'Every Thursday each active subscription is charged, retried once after a failure, then put on hold.',
  },
  {
    id: 'UC-08',
    name: 'Track Delivery',
    actors: ['Customer', 'Delivery Partner'],
    description: 'The customer follows the box using the delivery status updates received from the delivery partner.',
  },
  {
    id: 'UC-09',
    name: 'Rate Recipe',
    actors: ['Customer'],
    description: 'After delivery the customer gives a recipe one to five stars and an optional comment.',
  },
  {
    id: 'UC-10',
    name: 'Report Box Problem',
    actors: ['Customer'],
    description: 'The customer reports a missing or damaged item of a delivered box with a description.',
  },
  {
    id: 'UC-11',
    name: 'Publish Weekly Menu',
    actors: ['Menu Planner'],
    description: 'The menu planner publishes the recipes of a week with ingredients, nutrition facts and allergens.',
  },
  {
    id: 'UC-12',
    name: 'View Packing List',
    actors: ['Warehouse Staff'],
    description: 'After the cut-off warehouse staff see the generated list of boxes with their recipes and portions.',
  },
  {
    id: 'UC-13',
    name: 'Mark Box Packed',
    actors: ['Warehouse Staff'],
    description: 'Warehouse staff confirm a box is packed and print its shipping label, which triggers the shipment request.',
  },
  {
    id: 'UC-14',
    name: 'Request Shipment',
    actors: ['Delivery Partner'],
    description: 'Included when a box is packed: a shipment request is sent to the delivery partner API.',
  },
  {
    id: 'UC-15',
    name: 'Review Problem Report',
    actors: ['Administrator'],
    description: 'The administrator reads a problem report with its evidence and accepts or rejects it.',
  },
  {
    id: 'UC-16',
    name: 'Issue Credit',
    actors: [],
    description: 'Extension of the review: when the report is accepted a credit is added to the customer account.',
  },
  {
    id: 'UC-17',
    name: 'Manage Staff Accounts',
    actors: ['Administrator'],
    description: 'The administrator creates, updates and deactivates accounts of menu planners and warehouse staff.',
  },
  {
    id: 'UC-18',
    name: 'Manage Plans and Prices',
    actors: ['Administrator'],
    description: 'The administrator defines plans by meals and people and sets their weekly prices.',
  },
  {
    id: 'UC-19',
    name: 'View Revenue and Churn Reports',
    actors: ['Administrator'],
    description: 'The administrator reads weekly revenue and the share of subscriptions cancelled or paused.',
  },
  {
    id: 'UC-20',
    name: 'Send Notification',
    actors: ['Notification Service'],
    description: 'Included wherever a customer must be told something: the message is handed to the notification service.',
  },
];

// Question 4 — conceptual ERD: identifiers + key attributes, cardinality on both ends, verb labels, no foreign keys.
const ERD = `erDiagram
  CUSTOMER ||--o{ SUBSCRIPTION : holds
  PLAN ||--o{ SUBSCRIPTION : "is chosen in"
  SUBSCRIPTION ||--o{ BOX : generates
  BOX ||--|{ MEAL_SELECTION : contains
  RECIPE ||--o{ MEAL_SELECTION : "is chosen in"
  BOX ||--o{ PAYMENT : "is charged by"
  CUSTOMER ||--o{ RATING : gives
  RECIPE ||--o{ RATING : receives
  BOX ||--o{ PROBLEM_REPORT : "is reported in"
  PROBLEM_REPORT ||--o| CREDIT : "results in"
  CUSTOMER {
    string customerId PK
    string fullName
    string phone
    string deliveryAddress
  }
  PLAN {
    string planId PK
    int mealsPerWeek
    int people
    decimal weeklyPrice
  }
  SUBSCRIPTION {
    string subscriptionId PK
    date startDate
    string status
  }
  BOX {
    string boxId PK
    date deliveryWeek
    string status
  }
  RECIPE {
    string recipeId PK
    string name
    string allergens
  }
  MEAL_SELECTION {
    string selectionId PK
    int portions
  }
  PAYMENT {
    string paymentId PK
    datetime attemptedAt
    decimal amount
    string result
  }
  RATING {
    string ratingId PK
    int stars
    string comment
  }
  PROBLEM_REPORT {
    string reportId PK
    string description
    string decision
  }
  CREDIT {
    string creditId PK
    decimal amount
  }
`;

const ENTITIES = [
  {
    name: 'CUSTOMER',
    description: 'A person with a FreshBox account who receives boxes at a delivery address.',
    attributes: ['customerId', 'fullName', 'phone', 'deliveryAddress'],
  },
  {
    name: 'PLAN',
    description: 'An offer defined by meals per week and number of people, with a weekly price.',
    attributes: ['planId', 'mealsPerWeek', 'people', 'weeklyPrice'],
  },
  {
    name: 'SUBSCRIPTION',
    description: 'One customer subscribed to one plan from a start date; it can be active, paused or cancelled.',
    attributes: ['subscriptionId', 'startDate', 'status'],
  },
  {
    name: 'BOX',
    description: 'The weekly box generated for a subscription and a delivery week, packed and shipped.',
    attributes: ['boxId', 'deliveryWeek', 'status'],
  },
  {
    name: 'RECIPE',
    description: 'A dish published on a weekly menu with ingredients, nutrition facts and allergens.',
    attributes: ['recipeId', 'name', 'allergens'],
  },
  {
    name: 'MEAL_SELECTION',
    description: 'One recipe chosen for one box with its own number of portions.',
    attributes: ['selectionId', 'portions'],
  },
  {
    name: 'PAYMENT',
    description: 'One charge attempt of a box through the payment gateway, with its time, amount and result.',
    attributes: ['paymentId', 'attemptedAt', 'amount', 'result'],
  },
  {
    name: 'RATING',
    description: 'The stars and comment a customer gives to a recipe after delivery.',
    attributes: ['ratingId', 'stars', 'comment'],
  },
  {
    name: 'PROBLEM_REPORT',
    description: 'A report of a missing or damaged item in a delivered box, with the administrator decision.',
    attributes: ['reportId', 'description', 'decision'],
  },
  {
    name: 'CREDIT',
    description: 'An amount added to the customer account when a problem report is accepted.',
    attributes: ['creditId', 'amount'],
  },
];

